<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>订阅访问分析</title>
    <style>
        :root{--ink:#17212b;--muted:#65727e;--line:#dce3e8;--soft:#f6f8fa;--paper:#fff;--accent:#0d766d;--accent-soft:#e5f3f1;--amber:#a45109;--amber-soft:#fff4e8;--red:#b42318;--red-soft:#fff0ef}*{box-sizing:border-box}body{margin:0;background:#f2f5f7;color:var(--ink);font:14px Arial,sans-serif}.shell{max-width:1580px;margin:auto;padding:20px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center}.top h1{margin:0;font-size:23px}.top p{margin:4px 0 0;color:var(--muted)}button,input,select{font:inherit}.logout,.apply,.pager button{border:1px solid var(--line);border-radius:3px;background:#fff;padding:8px 11px;cursor:pointer}.apply{border-color:var(--accent);background:var(--accent);color:#fff;font-weight:600}.filters{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin-top:18px;padding:13px 14px;border:1px solid var(--line);background:var(--paper)}.filters label{display:grid;gap:5px;font-size:12px;color:var(--muted)}.filters input,.filters select{width:128px;min-height:34px;padding:7px 8px;border:1px solid var(--line);border-radius:3px;color:var(--ink);background:#fff}.filters .wide input{width:188px}.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin-top:14px;border:1px solid var(--line);background:var(--line)}.metric{padding:11px 14px;background:var(--paper)}.metric span{display:block;color:var(--muted);font-size:12px}.metric b{display:block;margin-top:5px;font-size:22px;line-height:1}.workspace{display:grid;grid-template-columns:370px minmax(0,1fr);gap:14px;margin-top:14px}.panel{border:1px solid var(--line);background:var(--paper)}.panel-head{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:13px 14px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:15px}.panel-head span{color:var(--muted);font-size:12px}.queue{max-height:calc(100vh - 235px);overflow:auto}.suspect{display:grid;grid-template-columns:38px minmax(0,1fr);gap:10px;width:100%;padding:12px 14px;border:0;border-bottom:1px solid #edf0f2;background:#fff;text-align:left;color:var(--ink);cursor:pointer}.suspect:hover,.suspect:focus-visible,.suspect.selected{background:var(--accent-soft);outline:0}.score{display:grid;place-items:center;align-self:start;width:38px;height:38px;border-radius:50%;background:var(--amber-soft);color:var(--amber);font-weight:700;font-size:12px}.score.high{background:var(--red-soft);color:var(--red)}.suspect-main{min-width:0}.suspect-email{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}.suspect-meta{margin-top:4px;color:var(--muted);font-size:12px}.signal-list{display:flex;flex-wrap:wrap;gap:4px;margin-top:7px}.signal{padding:2px 5px;border:1px solid var(--line);border-radius:2px;color:#45535f;font-size:11px}.empty{padding:22px 14px;color:var(--muted);font-size:12px}.case{min-width:0}.case-summary{padding:16px 15px;border-bottom:1px solid var(--line);background:var(--soft)}.case-summary h3{margin:0;font-size:17px}.case-summary p{margin:5px 0 0;color:var(--muted);font-size:12px}.case-grid{display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;margin-top:13px}.case-score{padding:12px;background:#fff;border:1px solid var(--line)}.case-score b{display:block;font-size:28px}.case-score span{color:var(--muted);font-size:12px}.case-signals{display:flex;align-content:start;flex-wrap:wrap;gap:6px}.case-signal{padding:5px 7px;border-left:3px solid var(--amber);background:#fff;color:#45535f;font-size:12px}.case-signal.high{border-left-color:var(--red)}.state{padding:30px 15px;color:var(--muted)}.table-wrap{overflow:auto}.logs{width:100%;min-width:900px;border-collapse:collapse;font-size:13px}.logs th,.logs td{padding:10px 12px;border-bottom:1px solid #edf0f2;text-align:left;vertical-align:top}.logs th{background:var(--soft);color:var(--muted);font-size:12px;font-weight:600}.logs tr:hover td{background:#fbfcfd}.subtle{color:var(--muted);font-size:12px}.user-agent{min-width:330px;max-width:520px;overflow-wrap:anywhere;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px}.badge{display:inline-block;padding:2px 6px;border-radius:9px;background:var(--accent-soft);color:#06685f;font-size:11px}.risk-badge{background:var(--red-soft);color:var(--red)}.pager{display:flex;align-items:center;gap:8px;padding:12px 15px}.pager button:disabled{opacity:.45;cursor:not-allowed}.pager span{color:var(--muted);font-size:12px}@media(max-width:960px){.workspace{grid-template-columns:1fr}.queue{max-height:360px}.summary{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){.shell{padding:14px}.top p{display:none}.filters label,.filters .wide{width:calc(50% - 5px)}.filters input,.filters select,.filters .wide input{width:100%}.summary{grid-template-columns:1fr}.case-grid{grid-template-columns:1fr}.queue{max-height:none}}
    </style>
</head>
<body>
<main class="shell">
    <header class="top"><div><h1>订阅访问分析</h1><p>将关联证据用于优先级排序，结论仍需人工复核。</p></div><button id="logout" class="logout" type="button">退出</button></header>
    <form id="filters" class="filters" aria-label="筛选条件">
        <label>开始日期<input name="start" type="date"></label><label>结束日期<input name="end" type="date"></label><label>邮箱<input name="email" placeholder="包含文本"></label><label>IP<input name="ip" placeholder="精确 IP"></label><label>国家<input name="country" maxlength="2" placeholder="US"></label><label class="wide">User-Agent<input name="user_agent" placeholder="客户端关键字"></label><label><span>仅代理</span><select name="proxy_only"><option value="">全部</option><option value="1">是</option></select></label><label><span>仅伪装</span><select name="masked_only"><option value="">全部</option><option value="1">是</option></select></label><button class="apply" type="submit">筛选记录</button>
    </form>
    <section id="stats" class="summary" aria-label="当前筛选摘要"></section>
    <section class="workspace">
        <aside class="panel"><div class="panel-head"><h2>嫌疑账户队列</h2><span>按可解释风险排序</span></div><div id="suspects" class="queue"></div></aside>
        <section class="panel case"><div class="panel-head"><h2>证据档案</h2><span id="case-status">选择账户查看记录</span></div><div id="case-summary" class="case-summary"><h3>尚未选择账户</h3><p>共享 User-Agent 仅是弱关联；请结合 IP、网络风险和访问时间线复核。</p></div><div id="state" class="state">正在加载记录...</div><div class="table-wrap"><table id="logs" class="logs" hidden><thead><tr><th>时间</th><th>用户</th><th>IP / 国家</th><th>网络风险</th><th>User-Agent</th><th>结果</th></tr></thead><tbody></tbody></table></div><div class="pager"><button id="prev" type="button">上一页</button><span id="page"></span><button id="next" type="button">下一页</button></div></section>
    </section>
</main>
<script>
const form=document.querySelector('#filters'),stats=document.querySelector('#stats'),suspectList=document.querySelector('#suspects'),table=document.querySelector('#logs'),body=table.querySelector('tbody'),state=document.querySelector('#state'),pageText=document.querySelector('#page'),caseSummary=document.querySelector('#case-summary'),caseStatus=document.querySelector('#case-status');let page=1,total=0,size=50,selectedSuspect=null,lastSuspects=[];
const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));const metrics={total_requests:'请求数',distinct_users:'独立用户',distinct_ips:'独立 IP'};const dataUrl='{{ $analysisBaseUrl }}/data',logoutUrl='{{ $analysisBaseUrl }}/logout';
function renderSummary(summary,suspects){stats.innerHTML=Object.entries(metrics).map(([key,label])=>'<div class="metric"><span>'+label+'</span><b>'+escape(summary[key])+'</b></div>').join('')+'<div class="metric"><span>待核查账户</span><b>'+escape(suspects.length)+'</b></div>'}
function renderSuspects(suspects){lastSuspects=suspects;if(!suspects.length){suspectList.innerHTML='<p class="empty">当前筛选范围内没有足够证据的账户。</p>';return}suspectList.innerHTML=suspects.map(suspect=>'<button class="suspect '+(selectedSuspect&&selectedSuspect.user_id===suspect.user_id?'selected':'')+'" type="button" data-suspect-email="'+escape(suspect.email)+'" data-filter-key="email" data-filter-value="'+escape(suspect.email)+'"><span class="score '+(suspect.risk_level==='高风险'?'high':'')+'">'+escape(suspect.risk_score)+'</span><span class="suspect-main"><span class="suspect-email">'+escape(suspect.email)+'</span><span class="suspect-meta">'+escape(suspect.risk_level)+' · '+escape(suspect.request_count)+' 次请求 · 最近 '+escape(suspect.last_seen_at)+'</span><span class="signal-list">'+suspect.signals.map(signal=>'<span class="signal">'+escape(signal.label)+' '+escape(signal.count)+'</span>').join('')+'</span></span></button>').join('')}
function renderCase(suspect){if(!suspect){caseSummary.innerHTML='<h3>尚未选择账户</h3><p>共享 User-Agent 仅是弱关联；请结合 IP、网络风险和访问时间线复核。</p>';caseStatus.textContent='选择账户查看记录';return}caseStatus.textContent='正在查看 '+suspect.email;caseSummary.innerHTML='<h3>'+escape(suspect.email)+' <span class="subtle">#'+escape(suspect.user_id)+'</span></h3><p>风险评分来自下列可解释证据，不代表已确认违规。</p><div class="case-grid"><div class="case-score"><b>'+escape(suspect.risk_score)+'</b><span>'+escape(suspect.risk_level)+'</span></div><div class="case-signals">'+suspect.signals.map(signal=>'<span class="case-signal '+(signal.label==='共享 IP'||signal.label==='高风险网络'?'high':'')+'">'+escape(signal.label)+'：'+escape(signal.count)+' 条记录</span>').join('')+'</div></div>'}
function renderLogs(logs){body.innerHTML=logs.data.map(row=>'<tr><td>'+escape(row.created_at)+'</td><td>'+escape(row.email)+'<br><span class="subtle">#'+escape(row.user_id)+'</span></td><td>'+escape(row.ip)+'<br><span class="subtle">'+escape(row.country_code)+'</span></td><td>'+(row.is_proxy?'<span class="badge">代理</span> ':'')+(row.fraud_score>=70?'<span class="badge risk-badge">'+escape(row.fraud_score)+'</span>':escape(row.fraud_score))+'</td><td class="user-agent" title="'+escape(row.user_agent)+'">'+escape(row.user_agent)+'</td><td>'+(row.masked?'<span class="badge">已伪装</span>':'原始域名')+'</td></tr>').join('');total=logs.total;page=logs.page;pageText.textContent='第 '+page+' 页 / 共 '+Math.max(1,Math.ceil(total/size))+' 页';document.querySelector('#prev').disabled=page===1;document.querySelector('#next').disabled=page*size>=total}
async function load(){const query=new URLSearchParams(new FormData(form));query.set('page',page);query.set('page_size',size);state.hidden=false;state.textContent='正在加载记录...';table.hidden=true;try{const response=await fetch(dataUrl+'?'+query,{credentials:'same-origin'});if(response.status===401){location.href='{{ $analysisBaseUrl }}';return}const payload=await response.json();if(!response.ok){state.textContent=payload.message||'加载失败';return}if(!selectedSuspect)renderSuspects(payload.suspects);renderSummary(payload.summary,selectedSuspect?lastSuspects:payload.suspects);renderCase(selectedSuspect);renderLogs(payload.logs);state.hidden=true;table.hidden=false}catch(error){state.textContent='加载失败，请稍后重试'}}
form.addEventListener('submit',event=>{event.preventDefault();page=1;selectedSuspect=null;load()});suspectList.addEventListener('click',event=>{const row=event.target.closest('[data-suspect-email]');if(!row)return;selectedSuspect=lastSuspects.find(suspect=>suspect.email===row.dataset.suspectEmail)||null;form.elements.email.value=row.dataset.filterValue;page=1;renderSuspects(lastSuspects);load()});document.querySelector('#prev').onclick=()=>{if(page>1){page--;load()}};document.querySelector('#next').onclick=()=>{if(page*size<total){page++;load()}};document.querySelector('#logout').onclick=async()=>{await fetch(logoutUrl,{method:'POST',credentials:'same-origin'});location.reload()};load();
</script>
<script>
const resetFilters=document.createElement('button');
resetFilters.id='reset-filters';
resetFilters.type='button';
resetFilters.className='logout';
resetFilters.textContent='重置筛选';
form.querySelector('.apply').before(resetFilters);
resetFilters.addEventListener('click',()=>{form.reset();page=1;selectedSuspect=null;load()});
</script>
</body>
</html>
